    /**
     * @method
     * @name nado#fetchMarkets
     * @description retrieves data on all markets for nado
     * @see https://docs.nado.xyz/developer-resources/api/gateway/queries/symbols
     * @see https://docs.nado.xyz/developer-resources/api/v2/pairs
     * @see https://docs.nado.xyz/developer-resources/api/v2/assets
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public java.util.concurrent.CompletableFuture<Object> fetchMarkets(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            Object symbolsRequest = this.gatewayPublicGetSymbols(parameters);
            Object pairsRequest = this.gatewayV2PublicGetPairs(parameters);
            Object assetsRequest = this.gatewayV2PublicGetAssets(parameters);
            Object responses = (Helpers.promiseAll(new java.util.ArrayList<Object>(java.util.Arrays.asList(symbolsRequest, pairsRequest, assetsRequest)))).join();
            Object symbols = this.safeList(responses, 0, new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            Object pairs = this.safeList(responses, 1, new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            Object assets = this.safeList(responses, 2, new java.util.ArrayList<Object>(java.util.Arrays.asList()));
            // product_id is a JSON number: JS object keys are always strings but a Python
            // dict keeps int keys, so indexBy would never match the safeString lookups below
            Object pairsById = new java.util.HashMap<String, Object>() {{}};
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(pairs)); i++)
            {
                Object rawPair = Helpers.GetValue(pairs, i);
                Object pairProductId = this.safeString(rawPair, "product_id");
                if (Helpers.isTrue(!Helpers.isEqual(pairProductId, null)))
                {
                    Helpers.addElementToObject(pairsById, pairProductId, rawPair);
                }
            }
            Object assetsById = new java.util.HashMap<String, Object>() {{}};
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(assets)); i++)
            {
                Object rawAsset = Helpers.GetValue(assets, i);
                Object assetProductId = this.safeString(rawAsset, "product_id");
                if (Helpers.isTrue(!Helpers.isEqual(assetProductId, null)))
                {
                    Helpers.addElementToObject(assetsById, assetProductId, rawAsset);
                }
            }
            Object assetsByCode = new java.util.HashMap<String, Object>() {{}};
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(assets)); i++)
            {
                Object rawAsset = Helpers.GetValue(assets, i);
                Object assetSymbol = this.safeString(rawAsset, "symbol");
                Object assetCode = this.safeCurrencyCode(this.removeMarketSuffix(assetSymbol));
                if (Helpers.isTrue(Helpers.isEqual(assetCode, null)))
                {
                    continue;
                }
                Object previous = this.safeDict(assetsByCode, assetCode);
                if (Helpers.isTrue(Helpers.isEqual(previous, null)))
                {
                    Helpers.addElementToObject(assetsByCode, assetCode, rawAsset);
                } else
                {
                    Object previousDeposit = this.safeBool(previous, "can_deposit", false);
                    Object previousWithdraw = this.safeBool(previous, "can_withdraw", false);
                    Object currentDeposit = this.safeBool(rawAsset, "can_deposit", false);
                    Object currentWithdraw = this.safeBool(rawAsset, "can_withdraw", false);
                    if (Helpers.isTrue(Helpers.isTrue(!Helpers.isTrue(previousDeposit) && !Helpers.isTrue(previousWithdraw)) && Helpers.isTrue((Helpers.isTrue(currentDeposit) || Helpers.isTrue(currentWithdraw)))))
                    {
                        Helpers.addElementToObject(assetsByCode, assetCode, rawAsset);
                    }
                }
            }
            Object markets = new java.util.ArrayList<Object>(java.util.Arrays.asList());
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(symbols)); i++)
            {
                Object market = Helpers.GetValue(symbols, i);
                Object id = this.safeString(market, "product_id");
                Object pair = this.safeDict(pairsById, id, new java.util.HashMap<String, Object>() {{}});
                Object asset = this.safeDict(assetsById, id, new java.util.HashMap<String, Object>() {{}});
                Object rawType = this.safeString(market, "type");
                Object type = ((Helpers.isTrue((Helpers.isEqual(rawType, "perp"))))) ? "swap" : rawType;
                Object contract = (Helpers.isEqual(type, "swap"));
                Object tickerId = this.safeString2(pair, "ticker_id", "tickerId");
                if (Helpers.isTrue(Helpers.isEqual(tickerId, null)))
                {
                    continue;
                }
                Object rawBaseId = this.safeString(market, "symbol");
                Object rawQuoteId = this.safeString(pair, "quote", "USDT0");
                Object base = this.safeCurrencyCode(this.removeMarketSuffix(rawBaseId));
                Object quote = this.safeCurrencyCode(rawQuoteId);
                Object baseAsset = this.safeDict(assetsByCode, base, asset);
                Object quoteAsset = this.safeDict(assetsByCode, quote);
                Object baseId = this.safeString(baseAsset, "product_id", rawBaseId);
                Object quoteId = this.safeString(quoteAsset, "product_id", rawQuoteId);
                Object settleId = ((Helpers.isTrue(contract))) ? quoteId : null;
                Object settle = ((Helpers.isTrue(contract))) ? quote : null;
                Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
                if (Helpers.isTrue(contract))
                {
                    symbol = Helpers.add(symbol, Helpers.add(":", settle));
                }
                Object tradingStatus = this.safeString(market, "trading_status");
                Object active = (!Helpers.isEqual(tradingStatus, "not_tradable"));
                Object priceIncrement = this.parseX18(this.safeString(market, "price_increment_x18"));
                Object amountIncrement = this.parseX18(this.safeString(market, "size_increment"));
                Object minCost = this.parseX18(this.safeString(market, "min_size"));
    final Object finalSymbol = symbol;
                final Object finalBase = base;
                final Object finalType = type;
                final Object finalTickerId = tickerId;
                            ((java.util.List<Object>)markets).add(this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
                    put( "id", id );
                    put( "lowercaseId", null );
                    put( "symbol", finalSymbol );
                    put( "base", finalBase );
                    put( "quote", quote );
                    put( "settle", settle );
                    put( "baseId", baseId );
                    put( "quoteId", quoteId );
                    put( "settleId", settleId );
                    put( "type", finalType );
                    put( "spot", (Helpers.isEqual(finalType, "spot")) );
                    put( "margin", null );
                    put( "swap", contract );
                    put( "future", false );
                    put( "option", false );
                    put( "active", active );
                    put( "contract", contract );
                    put( "linear", ((Helpers.isTrue(contract))) ? true : null );
                    put( "inverse", ((Helpers.isTrue(contract))) ? false : null );
                    put( "taker", NadoCore.this.parseX18(NadoCore.this.safeString(market, "taker_fee_rate_x18")) );
                    put( "maker", NadoCore.this.parseX18(NadoCore.this.safeString(market, "maker_fee_rate_x18")) );
                    put( "contractSize", ((Helpers.isTrue(contract))) ? 1 : null );
                    put( "expiry", null );
                    put( "expiryDatetime", null );
                    put( "strike", null );
                    put( "optionType", null );
                    put( "precision", new java.util.HashMap<String, Object>() {{
                        put( "amount", amountIncrement );
                        put( "price", priceIncrement );
                    }} );
                    put( "limits", new java.util.HashMap<String, Object>() {{
                        put( "leverage", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "amount", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "price", new java.util.HashMap<String, Object>() {{
                            put( "min", null );
                            put( "max", null );
                        }} );
                        put( "cost", new java.util.HashMap<String, Object>() {{
                            put( "min", minCost );
                            put( "max", null );
                        }} );
                    }} );
                    put( "created", null );
                    put( "info", NadoCore.this.extend(market, new java.util.HashMap<String, Object>() {{
                        put( "ticker_id", finalTickerId );
                        put( "name", NadoCore.this.safeString(asset, "name") );
                        put( "v2Pair", pair );
                        put( "v2Asset", asset );
                    }}) );
                }}));
            }
            return markets;
        });

    }

    /**
     * @method
     * @name nado#fetchCurrencies
     * @description fetches all available currencies on an exchange
     * @see https://docs.nado.xyz/developer-resources/api/v2/assets
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    public java.util.concurrent.CompletableFuture<Object> fetchCurrencies(Object... optionalArgs)
    {

        return java.util.concurrent.CompletableFuture.supplyAsync(() -> {

            Object parameters = Helpers.getArg(optionalArgs, 0, new java.util.HashMap<String, Object>() {{}});
            Object response = (this.gatewayV2PublicGetAssets(parameters)).join();
            Object result = new java.util.HashMap<String, Object>() {{}};
            Object assets = this.toArray(response);
            for (var i = 0; Helpers.isLessThan(i, Helpers.getArrayLength(assets)); i++)
            {
                Object currency = Helpers.GetValue(assets, i);
                Object parsed = this.parseCurrency(currency);
                Object code = this.safeString(parsed, "code");
                if (Helpers.isTrue(Helpers.isEqual(code, null)))
                {
                    continue;
                }
                Object previous = this.safeDict(result, code);
                Object canDeposit = this.safeBool(currency, "can_deposit", false);
                Object canWithdraw = this.safeBool(currency, "can_withdraw", false);
                if (Helpers.isTrue(Helpers.isEqual(previous, null)))
                {
                    Helpers.addElementToObject(result, code, parsed);
                } else
                {
                    Object previousDeposit = this.safeBool(previous, "deposit", false);
                    Object previousWithdraw = this.safeBool(previous, "withdraw", false);
                    if (Helpers.isTrue(Helpers.isTrue(!Helpers.isTrue(previousDeposit) && !Helpers.isTrue(previousWithdraw)) && Helpers.isTrue((Helpers.isTrue(canDeposit) || Helpers.isTrue(canWithdraw)))))
                    {
                        Helpers.addElementToObject(result, code, parsed);
                    }
                }
            }
            return result;
        });

    }

